use super::*;
use semio_framework_value_factory::OwnedValueRetirementFactory;
use semio_framework_value::retained_clone::RetainedCloneClose;
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn checked<T>(g:RetainedCloneGrant,call:impl FnOnce()->(T,RetainedCloneProgress))->T{let((value,p),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(call);assert!(p.fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));value}
fn close_value<T:semio_framework_value::retirement::RetireOwned>(value:T){let mut value=Some(value);let mut close=RetainedCloneClose::default();for _ in 0..10000{if value.is_none()&&close.is_empty(){return;}let g=grant(close.next_owner_demands::<T>(value.is_some(),&None,4096).unwrap());checked(g,||{let p=if let Some(step)=close.begin_granted(&mut value,g).unwrap(){step}else{close.step_granted(g).unwrap()};((),p.progress())});}panic!("original fixture owner remains");}
fn retire_slots(ledger:&mut ArtifactHistoryLedger<Vec<String>>){while ledger.retained_terminal_slot_count()>0{let g=RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()};let(visibility,progress)=ledger.retire_terminal_slot(g).unwrap();if let Some(visibility)=visibility{close_value(visibility);}assert!(progress.fits(g));}}
#[test]
fn original_history_input_returns_same_backing_and_captured_issuer(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("./🧫️fixtures/🔣️.json")).unwrap();
 for case in corpus["cases"].as_array().unwrap(){let original:Vec<String>=serde_json::from_value(case["operations"].clone()).unwrap();let backing=original.as_ptr();let mut ledger=ArtifactHistoryLedger::new();ledger.try_push(original).unwrap();let key=ledger.retained_read_key_at(0).unwrap();let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<Vec<String>>>=Arc::new(OwnedValueRetirementFactory::<Vec<String>>::default());let g=grant(OriginalHistorySource::<Vec<String>>::constructor_demand());let mut source=checked(g,||OriginalHistorySource::admit(key,&factory,g).unwrap().unwrap());let mut projections=Vec::new();
  for _ in 0..10{let d=source.root_demands(&ledger).unwrap();let g=grant(d);for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue};checked(denied,||{let step=source.advance_root(&mut ledger,denied).unwrap();assert_eq!(step.progress(),Default::default());((),step.progress())});assert_eq!(source.root_demands(&ledger).unwrap(),d);}let complete=checked(g,||{let step=source.advance_root(&mut ledger,g).unwrap();(matches!(step,RetainedCloneStep::Complete(_)),step.progress())});if complete{break;}}
  assert_eq!(source.borrow_original().unwrap().get().as_ptr(),backing);
  for index in case["readOrder"].as_array().unwrap(){let index=index.as_u64().unwrap()as usize;let mut output=None;for _ in 0..10{let d=source.demands(&ledger).unwrap();let g=grant(d);for axis in 0..5{let mut denied=g;match axis{0=>denied.maximum_items=0,1 if d.copy_bytes>0=>denied.maximum_copy_bytes-=1,2 if d.capacity_bytes>0=>denied.maximum_capacity_bytes-=1,3 if d.release_bytes>0=>denied.maximum_release_bytes-=1,4 if d.depth>0=>denied.maximum_depth-=1,_=>continue};let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.advance(&mut ledger,&mut output,index+1,|rows|&rows[index],denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(source.demands(&ledger).unwrap(),d);}
   checked(g,||{let step=source.advance(&mut ledger,&mut output,index+1,|rows|&rows[index],g).unwrap();((),step.progress())});if output.is_some(){break;}}
   let projection=output.unwrap();assert_eq!(projection.borrow().unwrap().get().as_ptr(),ledger.get(0).unwrap()[index].as_ptr());projections.push(projection);
  }
  let actual:Vec<&str>=projections.iter().map(|p|p.borrow().unwrap().get().as_str()).collect();assert_eq!(serde_json::to_value(actual).unwrap(),case["expected"]);source.begin_close();for mut p in projections{for _ in 0..10000{if p.terminal_is_empty(){break;}let g=grant(p.close_demand(4096).unwrap());checked(g,||{let step=p.close_step(g).unwrap();((),step.progress())});}assert!(p.terminal_is_empty());}
  for _ in 0..10000{if source.terminal_is_empty(){break;}let g=grant(source.close_demands(&ledger,4096).unwrap());checked(g,||{let step=source.close_step(&mut ledger,g).unwrap();((),step.progress())});}assert!(source.terminal_is_empty());assert_eq!(ledger.get(0).unwrap().as_ptr(),backing);assert!(ledger.get_mut(0).is_some());close_value(ledger.pop().unwrap());while ledger.retained_terminal_slot_count()>0{let g=RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()};let(visibility,progress)=ledger.retire_terminal_slot(g).unwrap();assert!(progress.fits(g));if let Some(visibility)=visibility{close_value(visibility);}}while !ledger.backing_is_empty(){let g=RetainedCloneGrant{maximum_items:1,maximum_release_bytes:ledger.next_empty_page_release_byte_demand().unwrap(),maximum_depth:1,..Default::default()};checked(g,||{let step=ledger.release_empty_page(g).unwrap();((),step.progress())});}let mut issuer=FactoryAuthority::new(factory);while !issuer.terminal_is_empty(){let g=grant(issuer.demands(4096).unwrap());checked(g,||{let step=issuer.step(g).unwrap();((),step.progress())});}
 }
}
#[test]
fn original_history_input_cancellation_restores_each_partial_birth_and_waits_for_live_producer(){
 for cutoff in 0..5{let original=vec!["original operation".repeat(1024)];let pointer=original[0].as_ptr();let mut ledger=ArtifactHistoryLedger::new();ledger.try_push(original).unwrap();let key=ledger.retained_read_key_at(0).unwrap();let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<Vec<String>>>=Arc::new(OwnedValueRetirementFactory::<Vec<String>>::default());let g=grant(OriginalHistorySource::<Vec<String>>::constructor_demand());let mut source=checked(g,||OriginalHistorySource::admit(key,&factory,g).unwrap().unwrap());let mut output=None;
  for _ in 0..cutoff{let g=grant(source.demands(&ledger).unwrap());checked(g,||{let step=source.advance(&mut ledger,&mut output,1,|ops|&ops[0],g).unwrap();((),step.progress())});}
  source.begin_close();let mut waited=output.is_none();for _ in 0..10000{if source.terminal_is_empty(){break;}let g=grant(source.close_demands(&ledger,4096).unwrap());let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||source.close_step(&mut ledger,g));match result{Ok(step)if step.progress()==RetainedCloneProgress::default()&&output.is_some()=>{assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let p=output.as_mut().unwrap();assert_eq!(p.borrow().unwrap().get().as_ptr(),pointer);while !p.terminal_is_empty(){let g=grant(p.close_demand(4096).unwrap());checked(g,||{let step=p.close_step(g).unwrap();((),step.progress())});}output=None;waited=true;},Ok(step)=>{assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));},Err(error)=>{assert_eq!(error.kind,ValueRefusalKind::WorkLimit);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let p=output.as_mut().expect("producer holds the original projection");assert_eq!(p.borrow().unwrap().get().as_ptr(),pointer);while !p.terminal_is_empty(){let g=grant(p.close_demand(4096).unwrap());checked(g,||{let step=p.close_step(g).unwrap();((),step.progress())});}output=None;waited=true;}}}
  assert!(source.terminal_is_empty()&&waited);assert_eq!(ledger.get(0).unwrap()[0].as_ptr(),pointer);close_value(ledger.pop().unwrap());while ledger.retained_terminal_slot_count()>0{let g=RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()};let(visibility,progress)=ledger.retire_terminal_slot(g).unwrap();assert!(progress.fits(g));if let Some(visibility)=visibility{close_value(visibility);}}while !ledger.backing_is_empty(){let g=RetainedCloneGrant{maximum_items:1,maximum_release_bytes:ledger.next_empty_page_release_byte_demand().unwrap(),maximum_depth:1,..Default::default()};checked(g,||{let step=ledger.release_empty_page(g).unwrap();((),step.progress())});}let mut issuer=FactoryAuthority::new(factory);while !issuer.terminal_is_empty(){let g=grant(issuer.demands(4096).unwrap());checked(g,||{let step=issuer.step(g).unwrap();((),step.progress())});}
 }
}
